content.arguments:
{"description":"Recompute aggregation correctly","command":"$p = Join-Path (Get-Location).Path 'sales.csv'
$rows = Import-Csv -LiteralPath $p
$sumO = 0; $sumA = 0
$g = $rows | Group-Object channel | Sort-Object Name
foreach ($x in $g) {
  $o = 0; $a = 0
  foreach ($r in $x.Group) { $o += [int]$r.orders; $a += [int]$r.amount }
  $sumO += $o; $sumA += $a
  "CHANNEL: {0} orders={1} amount={2} records={3}" -f $x.Name, $o, $a, $x.Count
}
"TOTAL: orders=$sumO amount=$sumA"
"CHECK online: 12+5=" + (12+5) + " 1200+600=" + (1200+600)
"CHECK all: $sumO $sumA""}
